import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import About from './components/About';
import ProgramsGrid from './components/ProgramsGrid';
import ImpactStats from './components/ImpactStats';
import SocialMediaFeed from './components/SocialMediaFeed';
import DonateSection from './components/DonateSection';
import Footer from './components/Footer';

const App: React.FC = () => {
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <div className="min-h-screen flex flex-col">
      <Navbar scrolled={scrolled} />

      <main className="flex-grow">
        <section id="hero">
          <Hero />
        </section>

        <section id="about" className="py-20 bg-desert">
          <About />
        </section>

        <section id="programs" className="py-20">
          <div className="container mx-auto px-4 md:px-8">
            <div className="max-w-3xl mb-16">
              <span className="text-coral font-bold uppercase tracking-widest text-sm mb-4 block">Our Focus</span>
              <h2 className="text-4xl md:text-5xl text-sea mb-6">Sustainable Growth Through Local Empowerment</h2>
              <p className="text-lg text-gray-700 leading-relaxed">
                We believe that true development happens at the intersection of environmental preservation and community prosperity. Our programs are designed to be measurable, long-term, and deeply rooted in the culture of Cabo del Este.
              </p>
            </div>
            <ProgramsGrid />
          </div>
        </section>

        <section className="bg-sea py-20 text-white overflow-hidden relative">
          <ImpactStats />
        </section>

        <section id="community" className="py-20 bg-desert">
          <div className="container mx-auto px-4 md:px-8">
            <div className="text-center max-w-2xl mx-auto mb-16">
              <h2 className="text-4xl text-sea mb-4">Life in Cabo del Este</h2>
              <p className="text-gray-600">Follow our journey and the stories of the people who make this community special.</p>
            </div>
            <SocialMediaFeed />
          </div>
        </section>

        <section id="donate" className="py-24 bg-white">
          <DonateSection />
        </section>
      </main>

      <Footer />
    </div>
  );
};

export default App;

import React, { useState } from 'react';

interface NavbarProps {
  scrolled: boolean;
}

const Navbar: React.FC<NavbarProps> = ({ scrolled }) => {
  const [isOpen, setIsOpen] = useState(false);

  const navLinks = [
    { name: 'Our Mission', href: '#about' },
    { name: 'Programs', href: '#programs' },
    { name: 'Community', href: '#community' },
