        <a href="#" className="flex items-center gap-2">
          <div className={`font-serif text-2xl font-bold ${scrolled ? 'text-sea' : 'text-white'}`}>
            FUNDACIÓN <span className="font-light">COSTA PALMAS</span>
          </div>
        </a>

        {/* Desktop Nav */}
        <div className="hidden md:flex items-center space-x-8">
          {navLinks.map((link) => (
            <a
              key={link.name}
              href={link.href}
              className={`text-sm font-medium tracking-wide uppercase transition-colors ${scrolled ? 'text-gray-700 hover:text-sea' : 'text-white/90 hover:text-white'}`}
            >
              {link.name}
            </a>
          ))}
          <a
            href="#donate"
            className={`px-6 py-2.5 rounded-full text-sm font-bold uppercase tracking-wider transition-all ${
              scrolled 
                ? 'bg-sea text-white hover:bg-opacity-90' 
                : 'bg-white text-sea hover:bg-opacity-90'
            }`}
          >
            Donate
          </a>
        </div>

        {/* Mobile Toggle */}
        <button 
          className="md:hidden"
          onClick={() => setIsOpen(!isOpen)}
        >
          <div className={`w-6 h-0.5 mb-1.5 transition-all ${scrolled ? 'bg-sea' : 'bg-white'}`}></div>
          <div className={`w-6 h-0.5 mb-1.5 transition-all ${scrolled ? 'bg-sea' : 'bg-white'}`}></div>
          <div className={`w-6 h-0.5 transition-all ${scrolled ? 'bg-sea' : 'bg-white'}`}></div>
        </button>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <div className="md:hidden absolute top-full left-0 w-full bg-white border-t p-6 shadow-xl animate-in fade-in slide-in-from-top-4">
          <div className="flex flex-col space-y-4">
