const ProgramsGrid: React.FC = () => {
  const [activeTab, setActiveTab] = useState<string>('All');
  const categories = ['All', 'Education', 'Environment', 'Community'];

  const filteredPrograms = activeTab === 'All' 
    ? PROGRAMS 
    : PROGRAMS.filter(p => p.category === activeTab);

  return (
    <div>
      <div className="flex flex-wrap gap-4 mb-12">
        {categories.map(cat => (
          <button
            key={cat}
            onClick={() => setActiveTab(cat)}
            className={`px-6 py-2 rounded-full text-sm font-bold tracking-wider transition-all border ${
              activeTab === cat 
                ? 'bg-sea text-white border-sea' 
                : 'bg-white text-gray-500 border-gray-200 hover:border-sea hover:text-sea'
            }`}
          >
            {cat}
          </button>
        ))}
      </div>

      <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
        {filteredPrograms.map(program => (
          <ProgramCard key={program.id} program={program} />
        ))}
      </div>
    </div>
  );
};

